# doppel-compat r12. The clones were placed with their feet level with the player's and nothing
# ever lowered them: a factory-spawned pawn cannot be moved after the spawn (SetLocation and
# SetPhysics are opcode natives), and forcing PHYS_Falling on one is how Minion Trap fell through
# the world (fragtrap_minions, 2026-09-20). So the floor is found BEFORE the spawn. Trace cannot run
# from Python; FindSpot hands a free point back unchanged, so the clone's own box is stepped down
# from the slot until something is under it, then bisected to about 1 uu.
GROUND_STEP = 16.0
GROUND_DEPTH = 600.0


def slot_ground(pawn, spot, radius, height):
    """(x, y, z) standing on the first floor below `spot`, or None."""
    extent = vec(radius, radius, height)

    def free(z):
        want = (spot[0], spot[1], z)
        try:
            result = pawn.FindSpot(extent, vec(*want))
        except Exception as exc:
            fault("slot floor", exc)
            return True
        return (isinstance(result, tuple) and len(result) >= 2 and bool(result[0])
                and distance(triple(result[1]), want) < 1.0)

    top = spot[2]
    z = top
    while z - GROUND_STEP >= top - GROUND_DEPTH:
        if not free(z - GROUND_STEP):
            lo, hi = z - GROUND_STEP, z
            for _ in range(4):
                mid = (lo + hi) * 0.5
                if free(mid):
                    hi = mid
                else:
                    lo = mid
            return (spot[0], spot[1], hi + 2.0)
        z -= GROUND_STEP
    return None
